<div class="backend-modal-backdrop" x-show="editing || transitionRow || detailRow" x-trap.inert.noscroll="editing || !!transitionRow || !!detailRow" @click.self="closeModal()">
    <section class="backend-modal" role="dialog" aria-modal="true" aria-labelledby="backend-dialog-title"><header><div><p class="eyebrow" x-text="label(resource)"></p><h3 id="backend-dialog-title" x-text="detailRow ? recordLabel(detailRow,resource) : transitionRow ? 'Mettre à jour le statut' : editingId ? 'Modifier la fiche' : createLabel()"></h3></div><button class="backend-icon-button" @click="closeModal()" :disabled="busy" aria-label="Fermer"><x-filament::icon icon="heroicon-o-x-mark"/></button></header>
        <div class="backend-notice backend-error" x-show="error" x-text="error"></div>
        <form x-show="editing" @submit.prevent="save()"><div class="backend-form"><template x-for="field in fields()" :key="field.key"><label :class="{'backend-field-wide':field.multiline}"><span><span x-text="field.label"></span><span class="backend-required" x-show="field.required"> *</span></span>
            <template x-if="field.options"><select x-model="form[field.key]" :name="field.key" :aria-label="field.label" :required="field.required"><option value="">Sélectionner…</option><template x-for="option in field.options" :key="option.value"><option :value="option.value" x-text="option.label"></option></template></select></template>
            <template x-if="!field.options && field.multiline"><textarea x-model="form[field.key]" :name="field.key" :aria-label="field.label" :required="field.required" rows="4"></textarea></template>
            <template x-if="!field.options && !field.multiline"><input x-model="form[field.key]" :name="field.key" :aria-label="field.label" :type="field.type" :required="field.required" :step="field.step" :min="field.min" :max="field.max"></template>
            <small x-show="field.key.endsWith('_minor')">Montant en dinars algériens (DA).</small><small x-show="field.key === 'month'">Choisir le premier jour du mois.</small><small x-show="field.type === 'datetime-local'">Heure locale d’Algérie.</small>
        </label></template></div><footer><button type="button" class="button secondary" @click="closeModal()" :disabled="busy">Annuler</button><button class="button" type="submit" :disabled="busy" x-text="busy ? 'Enregistrement…' : editingId ? 'Enregistrer les modifications' : 'Enregistrer'"></button></footer></form>
        <form x-show="transitionRow" @submit.prevent="saveTransition()"><div class="backend-form"><label class="backend-field-wide">Motif<input x-model="transitionReason" required minlength="3"></label><label x-show="transitionStatuses().length">Nouveau statut<select x-model="transitionStatus"><template x-for="state in transitionStatuses()" :key="state"><option :value="state" x-text="valueLabel(state)"></option></template></select></label></div><footer><button type="button" class="button secondary" @click="closeModal()" :disabled="busy">Annuler</button><button class="button" :disabled="busy">Confirmer</button></footer></form>
        <div x-show="detailRow"><dl class="backend-detail"><template x-for="field in detailFields()" :key="field"><div><dt x-text="fieldLabel(field)"></dt><dd dir="auto" x-text="display(detailRow?.[field],field)"></dd></div></template></dl><footer><button class="button secondary" @click="closeModal()">Fermer la fiche</button><button class="button" x-show="canManageRow()" @click="openForm(detailRow)">Modifier la fiche</button></footer></div>
    </section>
</div>
